//! Minimal re-implementation of the `SortedSet` interface used by the tests,
//! backed by the standard library's `BTreeSet` (a sorted set).

use std::collections::BTreeSet;

/// A sorted set of unique elements, mirroring `SortedSet<T>` from the
/// C++ `sortedcontainers` header for the operations the tests exercise.
pub struct SortedSet<T: Ord> {
    inner: BTreeSet<T>,
}

impl<T: Ord + Clone> SortedSet<T> {
    /// Create an empty set.
    pub fn new() -> Self {
        SortedSet {
            inner: BTreeSet::new(),
        }
    }

    /// Insert a value; duplicates are ignored.
    pub fn insert(&mut self, value: T) {
        self.inner.insert(value);
    }

    /// Return a new set containing all elements present in either set.
    pub fn union_with(&self, other: &SortedSet<T>) -> SortedSet<T> {
        SortedSet {
            inner: self.inner.union(&other.inner).cloned().collect(),
        }
    }

    /// Number of elements in the set.
    pub fn size(&self) -> usize {
        self.inner.len()
    }

    /// Whether the set contains the given value.
    pub fn contains(&self, value: &T) -> bool {
        self.inner.contains(value)
    }
}

impl<T: Ord + Clone> Default for SortedSet<T> {
    fn default() -> Self {
        Self::new()
    }
}

