mod sortedcontainers;

use sortedcontainers::SortedSet;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut n: i32 = 6;
    if args.len() > 1 {
        // Match C++ std::atoi: parse leading integer, 0 on failure.
        n = args[1].trim_start().parse::<i32>().unwrap_or(0);
    }

    let mut s1: SortedSet<i32> = SortedSet::new();
    let mut s2: SortedSet<i32> = SortedSet::new();
    for i in 0..n {
        s1.insert(i);
        s2.insert(i * 2);
    }

    let s3 = s1.union_with(&s2);

    println!("{}", s1.size());
    println!("{}", s2.size());
    println!("{}", s3.size());

    let mut line = String::new();
    for i in 0..n {
        // C++ prints bool as 1/0, each followed by a space.
        line.push_str(if s3.contains(&i) { "1 " } else { "0 " });
    }
    println!("{}", line);
}

